import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BuUvxvtQ.js";const p=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"web-app/settings.md","filePath":"web-app/settings.md"}'),n={name:"web-app/settings.md"};function s(i,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>The <strong>Settings</strong> page (<code>/settings</code>) controls appearance, dashboard behaviour, and layout.</p><p>Most preferences are stored in your browser only; only your <strong>unit preference</strong> is saved to your account (so it applies across the dashboard and the public API).</p><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile {#profile}&quot;">​</a></h2><p>Set the <strong>gender context</strong> used for outfit recommendations:</p><table tabindex="0"><thead><tr><th>Option</th><th>Behaviour</th></tr></thead><tbody><tr><td>Male</td><td>Recommendations use male-gendered context.</td></tr><tr><td>Female</td><td>Recommendations use female-gendered context.</td></tr><tr><td>Other</td><td>No specific gender context.</td></tr><tr><td>Other - Manual</td><td>Type your own (max 30 characters).</td></tr></tbody></table><p>This is stored locally and never sent to Sky Style except when required for an AI request.</p><h2 id="units" tabindex="-1">Units <a class="header-anchor" href="#units" aria-label="Permalink to &quot;Units&quot;">​</a></h2><p>Switch between <strong>metric</strong> (°C, km/h) and <strong>imperial</strong> (°F, mph). Saved to your account.</p><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance {#appearance}&quot;">​</a></h2><ul><li><strong>Theme</strong>: system, light, or dark.</li><li><strong>Reduce motion</strong>: minimises animated weather effects and interface transitions.</li></ul><h2 id="preferences" tabindex="-1">Preferences <a class="header-anchor" href="#preferences" aria-label="Permalink to &quot;Preferences {#preferences}&quot;">​</a></h2><ul><li><strong>Share my location with AI</strong> — include your location in the AI prompt for more relevant recommendations. When off, Sky Style still fetches weather for your coordinates but does not include your location text in the prompt sent to the AI. This setting is stored locally only.</li><li><strong>Weather only</strong> — show weather data without generating an AI outfit recommendation.</li><li><strong>Simple Mode default on Terms &amp; Privacy pages</strong> — show plain-English summaries.</li></ul><h2 id="dashboard-behaviour" tabindex="-1">Dashboard behaviour <a class="header-anchor" href="#dashboard-behaviour" aria-label="Permalink to &quot;Dashboard behaviour {#dashboard-behaviour}&quot;">​</a></h2><ul><li><strong>Weather Planning Panel</strong>: always open, closed by default, or disabled entirely.</li><li><strong>Default recommendation mode</strong>: Simple, Simple+, Advanced, or Pro (see <a href="./dashboard.html#recommendation-modes">Recommendation modes</a>).</li><li><strong>Follow-up mode</strong>: Replace or Chat (see <a href="./dashboard.html#follow-up-questions">Follow-up questions</a>).</li><li><strong>Session Diagnostics</strong>: show a diagnostics panel on the dashboard.</li><li><strong>BYOK panel</strong>: expand the Bring Your Own Key section by default.</li></ul><h2 id="layout-and-spacing" tabindex="-1">Layout &amp; spacing <a class="header-anchor" href="#layout-and-spacing" aria-label="Permalink to &quot;Layout &amp; spacing {#layout-and-spacing}&quot;">​</a></h2><ul><li><strong>Dashboard layout</strong>: Symmetrical Split, Large Weather (default), or Large Settings — with a live preview.</li><li><strong>Extra Side Spacing</strong>: add horizontal padding to selected pages — dashboard, account, settings, closet, feedback, inbox, and automatic recommendations.</li><li><strong>Custom Column Spacing</strong>: when on, drag the divider between dashboard panels to resize them freely. The ratio is saved automatically.</li></ul><h2 id="tutorials" tabindex="-1">Tutorials <a class="header-anchor" href="#tutorials" aria-label="Permalink to &quot;Tutorials {#tutorials}&quot;">​</a></h2><p>Replay any guided tour whenever you need a refresher:</p><ul><li><strong>Dashboard tour</strong> — choosing a location, setting preferences, and using follow-ups.</li><li><strong>API Dashboard tour</strong> — managing API keys and credits.</li><li><strong>Dev Dashboard tour</strong> — developer tooling (Dev users only).</li></ul>',20)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
